        Underweight: { bg: '#EFF6FF', color: '#1D4ED8', border: '#BFDBFE' },
        Normal: { bg: '#F0FDF4', color: '#15803D', border: '#86EFAC' },
        Overweight: { bg: '#FFFBEB', color: '#B45309', border: '#FDE68A' },
        Obese: { bg: '#FEF2F2', color: '#B91C1C', border: '#FECACA' },
    };
    const bmiTheme = bmiColors[category] || { bg: '#F8FAFC', color: '#475569', border: '#E2E8F0' };

    // ΓöÇΓöÇ Streak calculation ΓöÇΓöÇ
    const calcStreak = (historyArr) => {
        if (!historyArr || historyArr.length === 0) return 0;
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const days = [...new Set(
            historyArr.map(h => new Date(h.date).toISOString().split('T')[0])
        )].sort().reverse();

        let streak = 0;
        let cursor = new Date(today);
        for (const dayStr of days) {
            const d = new Date(dayStr);
            d.setHours(0, 0, 0, 0);
            const diff = Math.round((cursor - d) / 86400000);
            if (diff === 0 || diff === 1) {
                streak++;
                cursor = d;
            } else {
                break;
            }
        }
        return streak;
    };

    const streak = calcStreak(history || []);
    const streakEmoji = streak >= 30 ? '≡ƒÅå' : streak >= 14 ? '≡ƒöÑ' : streak >= 7 ? 'ΓÜí' : streak >= 3 ? 'Γ£¿' : '≡ƒôà';
    const streakMsg = streak >= 30 ? 'Incredible! Month-long streak!' : streak >= 14 ? 'Two weeks strong!' : streak >= 7 ? 'One week streak!' : streak >= 3 ? 'Great consistency!' : streak === 1 ? 'Streak started ΓÇö keep going!' : 'Log today to start your streak!';

    const bmiRanges = [
        { label: 'Underweight', range: '< 18.5', color: '#1D4ED8', bg: '#DBEAFE' },
        { label: 'Normal', range: '18.5 ΓÇô 24.9', color: '#15803D', bg: '#DCFCE7' },
        { label: 'Overweight', range: '25 ΓÇô 29.9', color: '#B45309', bg: '#FEF3C7' },
