                            <p style={{ color: '#475569', fontSize: '1rem', fontWeight: 500 }}>No advice received yet. Your coach will update you soon.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* ΓöÇΓöÇ Diet + Exercise row ΓöÇΓöÇ */}
